def sigToBlockType(sig: FunctionType): BlockType = sig match {
  case FunctionType(Nil, Nil) =>
    BlockType.ValueType()
  case FunctionType(Nil, resultType :: Nil) =>
    BlockType.ValueType(resultType)
  case _ =>
    BlockType.FunctionType(moduleBuilder.functionTypeToTypeID(sig))
}

private def toBlockType[T](value: T)(implicit ev: AsBlockType[T]): BlockType = {
  ev.toBlockType(value, this)
}

def ifThenElse[T : AsBlockType](blockType: T)(thenp: => Unit)(elsep: => Unit): Unit = {
  instrs += If(toBlockType(blockType))
  thenp
  instrs += Else
  elsep
  instrs += End
}

def ifThenElse()(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElse(BlockType.ValueType())(thenp)(elsep)

def ifThen[T : AsBlockType](blockType: T)(thenp: => Unit): Unit = {
  instrs += If(toBlockType(blockType))
  thenp
  instrs += End
}

def ifThen()(thenp: => Unit): Unit =
  ifThen(BlockType.ValueType())(thenp)

def block[T : AsBlockType, A](blockType: T)(body: LabelID => A): A = {
  val label = genLabel()
  instrs += Block(toBlockType(blockType), Some(label))
  val result = body(label)
  instrs += End
  result
}

def block[A]()(body: LabelID => A): A =
  block(BlockType.ValueType())(body)

def loop[T : AsBlockType, A](blockType: T)(body: LabelID => A): A = {
  val label = genLabel()
  instrs += Loop(toBlockType(blockType), Some(label))
  val result = body(label)
  instrs += End
  result
}

def loop[A]()(body: LabelID => A): A =
  loop(BlockType.ValueType())(body)

def whileLoop()(cond: => Unit)(body: => Unit): Unit = {
  loop() { loopLabel =>
    cond
    ifThen() {
      body
      instrs += Br(loopLabel)
    }
  }
}

def tryTable[T : AsBlockType, A](blockType: T)(clauses: List[CatchClause])(body: => A): A = {
  instrs += TryTable(toBlockType(blockType), clauses)
  val result = body
  instrs += End
  result
}

def tryTable[A]()(clauses: List[CatchClause])(body: => A): A =
  tryTable(BlockType.ValueType())(clauses)(body)

object FunctionBuilder {
  trait AsBlockType[T] {
    def toBlockType(value: T, builder: FunctionBuilder): BlockType
  }

  object AsBlockType {
    implicit val blockTypeInstance: AsBlockType[BlockType] = new AsBlockType[BlockType] {
      def toBlockType(value: BlockType, builder: FunctionBuilder): BlockType = value
    }

    implicit val typeInstance: AsBlockType[Type] = new AsBlockType[Type] {
      def toBlockType(value: Type, builder: FunctionBuilder): BlockType =
        BlockType.ValueType(value)
    }

    implicit val functionTypeInstance: AsBlockType[FunctionType] = new AsBlockType[FunctionType] {
      def toBlockType(value: FunctionType, builder: FunctionBuilder): BlockType =
        builder.sigToBlockType(value)
    }

    implicit val resultTypesInstance: AsBlockType[List[Type]] = new AsBlockType[List[Type]] {
      def toBlockType(value: List[Type], builder: FunctionBuilder): BlockType =
        builder.sigToBlockType(FunctionType(Nil, value))
    }
  }

